What is the output of the following code written in C?
void main()
{
printf("%d%d%d", 62, 062, 0x62);
}

What is the output of the code written in C?
 void main()
 {
     int k = 8, v = 8, i;
     i = k / ++v;
     printf("%d\n", i);
 }

What is the output of the code written in C?
 void main()
 {
     int k, val = 1;
     k = ++val * ++val;
     printf("%d", k);
 }

What is the output of the code written in C?
 void main()
 {
     printf("%d", 7 % -3);
     printf("%d", -7 % 3);
 }

What is the output of the following ‘C’ language statements?
 #include <stdio.h>
 int main() {
     int a = 10, b = 20, *p1 = &a, *p2 = &b;
     printf("Before : **p1=%d **p2=%d", *p1, *p2);
     *p1 = *p1 + *p2;
     *p2 = *p1 - *p2;
     *p1 = *p1 - *p2;
     printf("\nAfter : **p1=%d **p2=%d", *p1, *p2);
     return 0;
 }

